class Solution {
    static const int MOD=1000000007;
    int rows,cols;
    vector<vector<int>> apples;
    vector<vector<vector<int>>> memo;
    int dfs(int row,int col,int cuts){
        if(!apples[row][col])return 0;
        if(!cuts)return 1;
        int& cached=memo[row][col][cuts];
        if(cached!=-1)return cached;
        long long answer=0;
        for(int nextRow=row+1;nextRow<rows;++nextRow)if(apples[row][col]-apples[nextRow][col]>0)answer+=dfs(nextRow,col,cuts-1);
        for(int nextCol=col+1;nextCol<cols;++nextCol)if(apples[row][col]-apples[row][nextCol]>0)answer+=dfs(row,nextCol,cuts-1);
        return cached=answer%MOD;
    }
    public:int ways(vector<string>& pizza,int k){
        rows=pizza.size();
        cols=pizza[0].size();
        apples.assign(rows+1,vector<int>(cols+1));
        for(int row=rows-1;row>=0;--row)for(int col=cols-1;col>=0;--col)apples[row][col]=(pizza[row][col]=='A')+apples[row+1][col]+apples[row][col+1]-apples[row+1][col+1];
        memo.assign(rows,vector<vector<int>>(cols,vector<int>(k,-1)));
        return dfs(0,0,k-1);
    }
};
